  let previous:ListNode|null=null,node:ListNode|null=a;while(node){const next:ListNode|null=node.next;node.next=previous;previous=node;node=next;}for(node=previous;node;node=node.next)out.push(node.val);
  let answer=out.length?out[0]:0;for(const x of out)if(x>answer)answer=x;return answer;
}


python
def chainTurntablePeakTicket(head):
    a=head
    out=[]
    previous=None
    node=a
    while node:
        next_node=node.next
        node.next=previous
        previous=node
        node=next_node
    node=previous
    while node:
        out.append(node.val)
        node=node.next
    return max(out,default=0)


java
class Solution {
  public int chainTurntablePeakTicket(ListNode head) {
    ListNode a=head; List<Integer> out=new ArrayList<>();
    {ListNode previous=null,node=a;while(node!=null){ListNode next=node.next;node.next=previous;previous=node;node=next;}for(node=previous;node!=null;node=node.next)out.add(node.val);}
    int answer=out.isEmpty()?0:out.get(0);for(int x:out)answer=Math.max(answer,x);return answer;
  }
}
